create or replace package body t009_checkout_api as
  function order_total(p_order_id in number) return number is
    l_items number;
    l_is_physical boolean;
  begin
    -- Check if the order contains any physical items
    select max(CASE WHEN item_type = 'PHYSICAL' THEN 1 ELSE 0 END)
      into l_is_physical
      from t009_order_items
     where order_id = p_order_id;

    -- Calculate item total
    select nvl(sum(price * qty), 0)
      into l_items
      from t009_order_items
     where order_id = p_order_id;

    -- Add shipping cost only if there are physical items
    if l_is_physical = 1 then
      return l_items + t009_shipping_pkg.shipping_cost(p_order_id);
    else
      return l_items;
    end if;
  end order_total;
end t009_checkout_api;
/
